def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression using a stack-based approach to handle operator precedence
    and parentheses without recursion.
    """
    def precedence(op):
        return 1 if op in ('+', '-') else 2 if op in ('*', '/') else 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left / right)

    def tokenize(expression):
        token = ""
        for char in expression:
            if char.isdigit() or char == '.':
                token += char
            else:
                if token:
                    yield token
                    token = ""
                if char in "+-*/()":
                    yield char
        if token:
            yield token

    operators = []
    values = []

    for token in tokenize(expr.replace(" ", "")):
        if token.isdigit() or '.' in token:
            values.append(float(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            while (operators and precedence(operators[-1]) >= precedence(token)):
                apply_operator(operators, values)
            operators.append(token)

    while operators:
        apply_operator(operators, values)

    return values[0]

def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression using a top-down parsing approach with a focus on breaking down
    the expression into manageable parts directly, maintaining operator precedence and handling parentheses.
    """

    class Parser:
        def __init__(self, expression):
            self.expr = expression
            self.index = 0

        def current_char(self):
            if self.index < len(self.expr):
                return self.expr[self.index]
            return None

        def advance(self):
            self.index += 1

        def skip_whitespace(self):
            while self.current_char() and self.current_char().isspace():
                self.advance()

        def parse_number(self):
            num_str = []
            while self.current_char() and (self.current_char().isdigit() or self.current_char() == '.'):
                num_str.append(self.current_char())
                self.advance()
            return float(''.join(num_str))

        def parse_factor(self):
            self.skip_whitespace()
            if self.current_char() == '(':
                self.advance()  # skip '('
                result = self.parse_expression()
                self.advance()  # skip ')'
                return result
            return self.parse_number()

        def parse_term(self):
            result = self.parse_factor()
            while True:
                self.skip_whitespace()
                if self.current_char() == '*':
                    self.advance()
                    result *= self.parse_factor()
                elif self.current_char() == '/':
                    self.advance()
                    result /= self.parse_factor()
                else:
                    break
            return result

        def parse_expression(self):
            result = self.parse_term()
            while True:
                self.skip_whitespace()
                if self.current_char() == '+':
                    self.advance()
                    result += self.parse_term()
                elif self.current_char() == '-':
                    self.advance()
                    result -= self.parse_term()
                else:
                    break
            return result

    parser = Parser(expr)
    return parser.parse_expression()
